import type { LibraryArticle, LibrarySection, LibraryReference } from "./library";

export function decisionQueryGuides(de:boolean):LibraryArticle[]{
  const path=(en:string,german:string):`/${string}`=>de?`/de/lernen/${german}`:`/library/${en}`;
  const files=(name:string,kind:"csv"|"md",blank:string,example:string)=>[
    {label:blank,href:`/templates/${name}-${de?"de":"en"}.${kind}` as `/${string}`},
    {label:example,href:`/templates/${name}-example-${de?"de":"en"}.${kind}` as `/${string}`}
  ];
  const ref=(afterParagraph:number,en:string,german:string,labelEn:string,labelDe:string):LibraryReference=>({afterParagraph,before:de?"Hier kannst du":"Next, you can",label:de?labelDe:labelEn,href:path(en,german)});
  const shared={reviewedAt:"2026-10-10",image:"/images/guides/fanout-seo-decisions.webp",imageAlt:de?"Recherchefragen werden in Leseraufgaben, Belege und begründete Seitenentscheidungen eingeordnet.":"Research questions are mapped to reader tasks, evidence and justified page decisions.",sourceIds:["owner-decision-workflows-2026-10-10","google-ai-optimization"],toolCta:{title:de?"Nutze eine Frage, die du wirklich prüfen möchtest":"Use a question you actually need to investigate",copy:de?"Starte mit vorhandenem Material oder dem passenden Tool-Modus. Die Vorlagen benötigen keinen zusätzlichen Provider-Lauf.":"Start with existing material or the appropriate tool mode. The worksheets require no additional provider run.",button:de?"Kostenloses Tool öffnen":"Open the free tool"}};

  const priorities:LibraryArticle={...shared,number:"14",category:"Field guide",slug:de?"fanout-queries-priorisieren":"prioritize-fanout-queries",pairedSlug:de?"prioritize-fanout-queries":"fanout-queries-priorisieren",
    title:de?"Fanout-Queries priorisieren: zuerst die Entscheidung, dann der Aufwand":"Prioritize fanout queries by evidence, reader value and effort",
    seoTitle:de?"Fanout Queries priorisieren: Matrix und Beispiel":"Prioritize Query Fanout Queries: Decision Matrix and Example",
    shortTitle:de?"Fanout-Fragen priorisieren":"Prioritize fanout questions",
    description:de?"Priorisiere Fanout-Fragen mit einer editierbaren Matrix. Prüfe Leseraufgabe, Nachfragebelege, vorhandene Inhalte und Aufwand, ohne Rankingscores zu erfinden.":"Prioritize fanout questions with an editable matrix covering reader tasks, demand evidence, existing content and effort without inventing ranking scores.",
    primaryIntent:de?"Für geprüfte Cluster den nächsten sinnvollen Recherche- oder Content-Auftrag auswählen.":"Choose the next useful research or content assignment for reviewed clusters.",
    answer:de?"Priorisiere die Aufgabe, die du mit passenden Belegen tatsächlich lösen kannst. Prüfe zuerst Zielgruppe und vorhandene Seite, danach Nachfrage, Beleglücken und Aufwand. Die Matrix liefert eine begründete nächste Aktion; sie berechnet keine Ranking-Wahrscheinlichkeit.":"Prioritize the task you can actually solve with appropriate evidence. Review the audience and existing page first, then demand, evidence gaps and effort. The matrix produces a justified next action, not a ranking probability.",
    useWhen:de?"Für bereits geclusterte Fragen. Das ausgefüllte Beispiel nutzt vier redaktionelle Aufgaben eines fiktiven Kaufberaters; Nachfrage bleibt ausdrücklich ungeprüft.":"Use this with already clustered questions. The worked example uses four editorial tasks from a fictional buying guide; demand remains explicitly unchecked.",
    relatedSlugs:de?["fanout-queries-clustern","fanout-queries-search-console","content-brief-aus-fanout"]:["cluster-fanout-queries","fanout-queries-search-console","fanout-content-brief"],
    sections:[
      {id:"decision-gates",title:de?"Eine klare Prüfreihenfolge statt eines Gesamtscores":"Use a clear review order instead of one total score",paragraphs:de?[
        "Beginne mit reader_job. Kannst du benennen, was jemand nach der Seite tun oder entscheiden soll? Passt diese Person zu deiner Website? Die SQL-Frage aus unserem Beispiel scheidet hier aus. Ein hoher hypothetischer Suchwert würde aus einer fachfremden Aufgabe noch keinen passenden Auftrag machen.",
        "Prüfe als Nächstes existing_page. Eine vorhandene passende Seite kann einen Kostenabschnitt aufnehmen, auch wenn die Kostenfragen einen eigenen Cluster bilden. Verschiebe keine Leseraufgabe auf eine neue URL, nur damit jede Matrixzeile eine Seite bekommt. Schreibe die beabsichtigte Aktion auf, bevor du einen Aufwand schätzt.",
        "Drei weitere Spalten halten Nachfragebelege, vorhandene Evidenz und Aufwand auseinander. not_checked ist eine offene Prüfung, keine schlechte Bewertung. research_required sagt, dass eine belastbare Empfehlung noch Arbeit braucht. Verwende eigene Aufwandskategorien mit einer verständlichen Bedeutung für dein Team; ein universelles Gewichtungsschema passt selten zu jeder Website.",
        "Die leere CSV enthält zehn Felder. Lade sie zusammen mit dem Beispiel herunter. Jede Entscheidung bekommt in reason einen Satz und in next_action eine überprüfbare Aufgabe. So kann eine zweite Person verstehen, warum ein Thema vorgezogen oder zurückgestellt wurde."
      ]:[
        "Start with reader_job. Can you state what someone should do or decide after reading the page? Does that person fit your website? The SQL question in our exercise fails this review. A hypothetical high search volume would not make an unrelated task relevant to the assignment.",
        "Next, review existing_page. A suitable page can absorb a cost section even if the cost questions have their own cluster. Do not move a reader task onto another URL just so every worksheet row becomes a page. Record the intended action before estimating its effort.",
        "Three further columns keep demand evidence, evidence readiness and effort separate. not_checked means a check is open, not that the task scored badly. research_required means a reliable recommendation still needs work. Use effort categories your team can explain; a universal weighting scheme rarely suits every website.",
        "The blank CSV has ten fields. Download it alongside the example. Give every decision a sentence in reason and a checkable task in next_action. A second person should be able to understand why something was advanced or deferred."
      ],downloads:files("fanout-priorities","csv",de?"Leere Priorisierungsmatrix (CSV)":"Blank prioritization matrix (CSV)",de?"Ausgefüllte Entscheidungsmatrix (CSV)":"Completed decision matrix (CSV)"),references:[ref(2,"fanout-queries-search-console","fanout-queries-search-console","check fanout against Search Console","Fanout mit Search Console prüfen")]},
      {id:"worked-priorities",title:de?"Vier Aufgaben führen zu unterschiedlichen nächsten Schritten":"Four tasks lead to different next steps",paragraphs:de?[
        "Im Beispiel ist die Softwareauswahl für ein kleines Team fachlich passend, braucht aber geprüfte Funktionen, Berechtigungen und Preise. Ihre Entscheidung lautet research_first. Das ist keine Ablehnung des Themas: Die Redaktion erhält zunächst einen Rechercheauftrag, bevor sie einen Sieger benennt.",
        "Der Kosten-Cluster gehört zur gleichen Kaufentscheidung. Die Matrix hält /seo-tools als vorhandenes fiktives Ziel fest und nennt section_candidate. Vorrangig fehlen die aktuellen Nutzerbedingungen. Erst wenn die Rechnung geprüft ist, lässt sich ein hilfreicher Kostenabschnitt formulieren.",
        "Der Import-Cluster benötigt eine korrekt importierte Datei als Ergebnis. Seine eigene Aufgabe ist test_first: Unicode und Textfelder tatsächlich prüfen. Die Nachfrage bleibt offen, doch der kleine Test kann zunächst klären, ob überhaupt eine verlässliche Anleitung möglich ist. Das macht ihn zu einem begrenzten Prüfauftrag, nicht automatisch zur wichtigsten neuen Landingpage.",
        "Diese Reihenfolge ist eine redaktionelle Entscheidung im Lehrfall. Sie stammt weder aus gemessenen Kundenprioritäten noch aus einem Fanout-Score. Ändert sich der Auftrag, kann sich auch die Reihenfolge ändern; halte die neue Begründung und das Prüfdatum fest."
      ]:[
        "In the example, software selection for a small team is relevant but needs verified features, permissions and prices. Its decision is research_first. That does not reject the topic: the editor receives a research assignment before naming a winner.",
        "The cost cluster belongs to the same purchasing decision. The matrix retains the fictional existing /seo-tools target and records section_candidate. Current seat conditions are the main gap. Only after checking the calculation can the editor produce a useful cost section.",
        "The import cluster needs a correctly imported file as its outcome. Its next action is test_first: actually check Unicode and text fields. Demand is still unknown, but a bounded test can first establish whether a reliable tutorial is possible. That is an investigation, not automatic proof that this is the most important new landing page.",
        "This order is an editorial decision within the exercise. It comes neither from measured customer priorities nor a fanout score. When the assignment changes, the order may change too; retain the new reason and review date."
      ]},
      {id:"review-priority",title:de?"Eine Priorität braucht einen Verantwortlichen und einen Abnahmebeleg":"Give a priority an owner and acceptance evidence",paragraphs:de?[
        "Übertrage die gewählte Aufgabe in einen Brief mit Zuständigkeit, benötigten Quellen und einem klaren Abschlusskriterium. Eine Liste mit hoch, mittel und niedrig hilft wenig, wenn niemand weiß, was als erledigt zählt. Für die Nutzerkosten kann die Abnahme eine nachvollziehbare Rechnung aus datierten offiziellen Bedingungen sein.",
        "Prüfe die Matrix erneut, wenn eine neue Quelle, ein Nachfragebeleg oder ein bereits veröffentlichtes Ergebnis vorliegt. Halte ausgeschlossene und zurückgestellte Aufgaben erhalten, damit eine spätere Überarbeitung ihre Begründung sieht. Unbekannte Nachfrage bleibt ein Recherchepunkt und wird nicht unbemerkt als null in einen Score umgerechnet.",
        "Nach einer tatsächlichen Änderung gehört die URL in den Messplan. So verbindet die Priorisierung eine sinnvolle nächste Aufgabe mit einem späteren Review, ohne aus dem Plan bereits einen Erfolg zu machen."
      ]:[
        "Move the chosen task into a brief with ownership, required sources and a clear completion criterion. A high/medium/low list helps little if nobody knows what counts as finished. For seat cost, acceptance could be a reproducible calculation from dated official conditions.",
        "Review the matrix when a new source, demand observation or published result becomes available. Retain excluded and deferred tasks so a later review can see their reasons. Unknown demand stays a research question and is not silently converted into a zero score.",
        "After a real change, put the URL into the measurement plan. Prioritization then connects a useful next task to a later review without presenting the plan itself as success."
      ],references:[ref(0,"fanout-content-brief","content-brief-aus-fanout","create a content brief","einen Content-Brief erstellen"),ref(2,"measure-fanout-content-changes","fanout-content-aenderungen-messen","measure content changes","Content-Änderungen messen")]}
    ]};

  const measurement:LibraryArticle={...shared,number:"15",category:"Measurement",slug:de?"fanout-content-aenderungen-messen":"measure-fanout-content-changes",pairedSlug:de?"measure-fanout-content-changes":"fanout-content-aenderungen-messen",
    title:de?"Fanout-Content-Änderungen messen: Release, Recrawl und vergleichbare Daten":"Measure fanout content changes with a comparable baseline",
    seoTitle:de?"Fanout Content Änderungen messen: Plan und Beispiel":"Measure Query Fanout Content Changes: Plan and Example",
    shortTitle:de?"Content-Änderungen messen":"Measure content changes",
    description:de?"Dokumentiere Release, Recrawl und vergleichbare GSC-Fenster. Mit editierbarem Messplan, Änderungsprotokoll und synthetischem Vorher-/Nachher-Beispiel.":"Record release, recrawl and comparable GSC windows with an editable measurement plan, change log and synthetic before-and-after exercise.",
    sourceIds:[...shared.sourceIds,"gsc-dimensions-2026-10-10","gsc-performance-data-2026-10-10"],
    primaryIntent:de?"Die Entwicklung einer geänderten Seite beobachten und die Grenzen eines Vorher-/Nachher-Vergleichs erhalten.":"Observe a changed page while preserving the limits of a before-and-after comparison.",
    answer:de?"Lege vor der Änderung URL, Query-Kohorte, Filter und Kennzahl fest. Dokumentiere Release und bestätigten Recrawl getrennt, vergleiche passende Zeitfenster und halte Störfaktoren fest. Ein beobachteter Anstieg belegt nicht automatisch, dass die Fanout-Recherche ihn verursacht hat.":"Before changing content, fix the URL, query cohort, filters and metric. Record release and confirmed recrawl separately, compare suitable windows and retain confounders. An observed increase does not automatically establish that fanout research caused it.",
    useWhen:de?"Nach einem tatsächlichen Content-Release. Die Download-Übung ist vollständig synthetisch; ihre Zahlen sind keine Ergebnisse dieser Website.":"Use this after a real content release. The downloadable exercise is wholly synthetic; its figures are not this website's results.",
    relatedSlugs:de?["fanout-queries-search-console","query-fanout-report-vorlage","content-brief-aus-fanout"]:["fanout-queries-search-console","query-fanout-report-template","fanout-content-brief"],
    sections:[
      {id:"fixed-scope",title:de?"Den Vergleich vor der Veröffentlichung festlegen":"Define the comparison before publishing",paragraphs:de?[
        "Schreibe zuerst auf, welche Entscheidung die Nachmessung ermöglichen soll. Soll ein Kostenabschnitt verständlicher werden, interessiert dich eine passende Auswahl-/Kosten-Kohorte auf dieser URL. Der gesamte Property-Traffic beantwortet diese Frage nur indirekt und kann ganz andere Themen enthalten.",
        "Der Messplan hält Property, Suchtyp, Sprache, Länder-, Geräte- und Darstellungsfilter fest. Bewahre auch die genaue Query-Auswahl auf. Gleich benannte Kohorten mit später ergänzten Queries sind keine unveränderte Stichprobe. Bei einer neuen Seite ohne Verlauf bleibt die eigene Baseline fehlend; vorhandene thematische Seiten sind nur eine Vergleichshilfe.",
        "Wähle vollständige Berichtstage und Fenster gleicher Länge mit vergleichbaren Wochentagen. 28 Tage sind im Lehrbeispiel eine Arbeitsentscheidung, keine universelle Mindestdauer. Berichtslatenz, Saison und geringe Datenmengen können ein längeres Fenster erfordern. Notiere diese Entscheidung, bevor du einen günstigen Ausschnitt suchst.",
        "Die editierbare Markdown-Datei verbindet Messdefinition, Änderungsprotokoll und Auswertung. Sie lässt sich ohne zusätzliches Tracking oder einen neuen Provider-Lauf ausfüllen. Werte, die dein bestehender Datenumfang nicht liefert, bleiben unbekannt."
      ]:[
        "Start by stating the decision the follow-up should support. If you revise a cost section, the relevant selection/cost cohort on that URL is useful. Total property traffic answers this only indirectly and may include unrelated subjects.",
        "The plan records property, search type, language, country, device and search-appearance filters. Retain the exact query selection too. Cohorts with the same label but additional queries are not an unchanged sample. A new page without history has no page baseline; existing topical pages offer orientation only.",
        "Choose complete reporting days and equal-length windows with comparable weekdays. Twenty-eight days is an editorial choice in the exercise, not a universal minimum. Reporting latency, seasonality and sparse data may require a longer window. Record the choice before looking for a favourable subset.",
        "The editable Markdown file connects a measurement definition, change log and review. You can fill it without additional tracking or a new provider run. Values your existing data source cannot supply remain unknown."
      ],downloads:files("fanout-measurement","md",de?"Editierbarer Messplan (Markdown)":"Editable measurement plan (Markdown)",de?"Synthetische Messübung (Markdown)":"Synthetic measurement exercise (Markdown)"),references:[ref(1,"fanout-queries-search-console","fanout-queries-search-console","map fanout to GSC data","Fanout mit GSC abgleichen")]},
      {id:"release-recrawl",title:de?"Release und Recrawl sind zwei verschiedene Zeitpunkte":"Release and recrawl are different events",paragraphs:de?[
        "Ein erfolgreicher Release zeigt, dass die Änderung online ist. Er zeigt nicht, ob Google sie bereits neu gecrawlt, indexiert oder anders eingeordnet hat. Dokumentiere den ersten bestätigten Recrawl anhand einer tatsächlichen Prüfung; unbekannte Crawl-Zeiten bleiben unbekannt.",
        "Im fiktiven Änderungsprotokoll werden Titel und Kostenabschnitt gleichzeitig angepasst. Der Vorher-/Nachher-Vergleich kann ihren Einfluss nicht getrennt bestimmen. Füge auch andere Releases, veränderte Nachfrage, Wettbewerber und mögliche Algorithmusänderungen hinzu. Ein Protokoll mit diesen Grenzen ist hilfreicher als eine scheinbar präzise Ursache.",
        "Trenne technische Freigabe, Suchmessung und Nutzung. HTTP 200 und korrekte Canonicals prüfen die Veröffentlichung. Klicks und Impressionen beschreiben Sichtbarkeit im gewählten Suchumfang. Eine vorhandene datenschutzgerechte Download- oder Tool-Kennzahl beschreibt einen weiteren Schritt. Keine dieser Ebenen ersetzt die anderen.",
        "Addiere überlappende gefilterte Berichte nicht zu einer Gesamtsumme. Auch sichtbare Query-Zeilen bilden nicht zwingend den Property-Gesamtwert ab. Halte die originale Aggregation und Datenbegrenzung für beide Fenster fest."
      ]:[
        "A successful release shows that the change is online. It does not show whether Google has recrawled, indexed or re-evaluated it. Record the first confirmed recrawl from an actual check; unknown crawl times stay unknown.",
        "The fictional change log revises the title and cost section together. A before-and-after comparison cannot separate their effects. Add other releases, changing demand, competitors and possible algorithm changes. A log retaining those limits is more useful than an apparently precise cause.",
        "Keep technical release, search measurement and usage separate. HTTP 200 and correct canonicals verify publication. Clicks and impressions describe visibility within the chosen search scope. An existing privacy-aware download or tool metric describes another step. None of these replaces the others.",
        "Do not add overlapping filtered reports into a total. Visible query rows may not represent the whole property total either. Retain the original aggregation and coverage limits for both windows."
      ]},
      {id:"synthetic-review",title:de?"Doppelte Klicks bei gleicher CTR ehrlich berichten":"Report doubled clicks with unchanged CTR accurately",paragraphs:de?[
        "Die eigene Rechenübung enthält 10 Klicks bei 1000 Impressionen und später 20 bei 2000. In beiden Fenstern beträgt die CTR ein Prozent. Die Klickzahl hat sich im synthetischen Fall verdoppelt, die Klickrate nicht. Eine Durchschnittsposition lässt sich aus diesen beiden Werten nicht herleiten.",
        "Der zulässige Befund beschreibt die Zahlen und ihren festen Umfang. Die Vermutung, ein neuer Abschnitt habe zusätzliche passende Fragen abgedeckt, bleibt eine Hypothese. Nachfrage, Query-Mix und gleichzeitige Änderungen sind weitere mögliche Erklärungen. Für geringe Stichproben hilft ein weiteres vergleichbares Fenster mehr als eine dramatische Prozentüberschrift.",
        "Halte zum Abschluss nächste Aufgabe, zuständige Person und Prüftermin fest. Du kannst etwa die neu sichtbaren Fragen auf inhaltliche Passung prüfen oder fehlende Crawl-Evidenz ergänzen. Übernimm Beobachtung, Hypothese und Empfehlung getrennt in den Bericht; ein Messplan ist noch kein Ranking-Erfolg."
      ]:[
        "The original arithmetic exercise has 10 clicks from 1000 impressions and later 20 from 2000. CTR is one percent in both windows. Clicks doubled in the synthetic case; click-through rate did not. Average position cannot be derived from those two values.",
        "The supported finding states the numbers within their fixed scope. The suggestion that a new section covered additional relevant questions remains a hypothesis. Demand, query mix and simultaneous changes are other possible explanations. With small samples, another comparable window is more useful than a dramatic percentage headline.",
        "Finish with a next task, owner and review date. You might review the relevance of newly visible questions or obtain missing crawl evidence. Carry observation, hypothesis and recommendation separately into the report; a measurement plan is not a ranking success."
      ],references:[ref(2,"query-fanout-report-template","query-fanout-report-vorlage","write a bounded fanout report","einen begrenzten Fanout-Bericht schreiben")]}
    ]};

  const sources:LibraryArticle={...shared,number:"16",category:"Measurement",slug:de?"fanout-quellen-pruefen":"fanout-source-audit",pairedSlug:de?"fanout-source-audit":"fanout-quellen-pruefen",
    image:"/images/guides/ai-citations.webp",imageAlt:de?"Ein Dokument wird mit zugehörigen Quellen verbunden; getrennte Markierungen zeigen die Grenzen der Zuordnung.":"A document is connected to supporting sources, with separate markers showing attribution limits.",
    title:de?"Fanout-Quellen prüfen: welche Quelle trägt welche Aussage?":"Audit fanout sources one claim at a time",
    seoTitle:de?"Fanout Quellen prüfen: Audit-CSV und Beispiel":"Query Fanout Source Audit: CSV Checklist and Example",
    shortTitle:de?"Fanout-Quellen prüfen":"Audit fanout sources",
    description:de?"Prüfe Claim, Belegstelle, Aktualität und Quellenumfang mit einer eigenen CSV. Das annotierte Beispiel enthält eine gestützte und zwei zurückgewiesene Aussagen.":"Review claims, evidence locations, freshness and source scope with an original CSV. The annotated example includes one supported and two rejected claims.",
    primaryIntent:de?"Eine konkrete Behauptung gegen eine auflösbare Quelle mit passendem Umfang prüfen.":"Check a specific claim against a resolvable source with appropriate scope.",
    answer:de?"Prüfe zuerst den genauen Claim, danach die passende Belegstelle. Eine verlinkte Quelle muss die Aussage tatsächlich tragen, aktuell genug sein und zum angegebenen Umfang passen. Das Arbeitsblatt hält auch unbelegte Aussagen und gemeinsame Eigentümer fest.":"Review the exact claim first, then the relevant evidence location. A linked source must actually support the statement, be sufficiently current and match its attributed scope. The worksheet also retains unsupported claims and common ownership.",
    useWhen:de?"Vor einem Brief, einer Empfehlung oder einem Bericht. Das eigene Beispiel prüft öffentliche Dokumentation und die Eigentümeroffenlegung, ohne neue Provider-Ausgaben zu speichern.":"Use this before a brief, recommendation or report. The original exercise checks public documentation and ownership disclosure without retaining new provider output.",
    relatedSlugs:de?["ki-zitate-und-quellen","content-brief-aus-fanout","query-fanout-report-vorlage"]:["ai-citations","fanout-content-brief","query-fanout-report-template"],
    sections:[
      {id:"claim-register",title:de?"Die Aussage klein genug machen, um sie prüfen zu können":"Make the claim specific enough to check",paragraphs:de?[
        "Schreibe einen prüfbaren Satz in claim. Eine Quelle kann erklären, wie ein Suchfeature funktioniert, ohne die Sichtbarkeit deiner Website zu messen. Trenne diese beiden Aussagen im Register, selbst wenn ein Entwurf sie bisher in einem Satz verbindet.",
        "Das CSV-Arbeitsblatt enthält Belegstelle, Datum, Umfang, Eigentümerbeziehung, Urteil und nächsten Schritt. Die URL allein reicht nicht: Eine andere Person soll den relevanten Abschnitt finden und nachvollziehen können, weshalb er die Aussage stützt. Bei Preisen, Verfügbarkeit und Funktionen braucht die Redaktion einen passenden Markt und einen aktuellen Stand.",
        "Bewahre den Quellenumfang aus deinem nativen Export. Eine Laufquelle ist kein Beleg dafür, dass jede Query genau diese Seite verwendet hat. Wo eine Beziehung fehlt, bleibt sie fehlend. Markiere einen toten Link als nicht prüfbar und suche für die Aussage eine zulässige aktuelle Quelle, statt den alten Titel als Beweis zu behandeln.",
        "Leere und ausgefüllte CSV zeigen denselben Prüfweg. origin kennzeichnet, dass das Beispiel redaktionell ist. Die Lehrdatei enthält keine erzeugten Provider-Queries, privaten Suchdaten oder vollständigen Kopien der externen Texte."
      ]:[
        "Write a checkable sentence in claim. A source may explain how a search feature works without measuring your website's visibility. Separate those statements in the register even if a draft currently combines them.",
        "The CSV records evidence location, date, scope, ownership relationship, verdict and next step. A URL alone is insufficient: another reviewer should be able to find the relevant section and understand why it supports the statement. Prices, availability and features need an appropriate market and current review.",
        "Preserve source scope from your native export. A run-level source does not prove every query used that particular page. Missing relationships stay missing. Mark a dead link as uncheckable and find a permissible current source for the claim rather than treating the old title as proof.",
        "Blank and completed CSV files follow the same review process. origin marks the exercise as editorial. It contains no generated provider queries, private search data or complete copies of external text."
      ],downloads:files("fanout-source-audit","csv",de?"Leeres Claim- und Quellenregister (CSV)":"Blank claim and source register (CSV)",de?"Annotierte Quellenprüfung (CSV)":"Annotated source audit (CSV)"),references:[ref(2,"ai-citations","ki-zitate-und-quellen","interpret citations and source scope","Zitate und Quellenumfang einordnen")]},
      {id:"annotated-audit",title:de?"Ein gestützter Claim und zwei notwendige Korrekturen":"One supported claim and two necessary corrections",paragraphs:de?[
        "c01 verweist auf Googles Abschnitt zur fortbestehenden Relevanz von SEO für generative Suchfunktionen. Diese Primärquelle trägt die allgemeine Aussage. Das Urteil lautet supported und der Umfang general_guidance. Ein individuelles Ergebnis für deinen Artikel wird dadurch nicht gemessen.",
        "c02 verwendet dieselbe Quelle für die erfundene Behauptung, unsere Seite ranke deshalb auf Platz eins. Der Text enthält keine entsprechende Website-Messung. Das Urteil lautet unsupported, die Folgeaufgabe ist das Entfernen der Ranking-Behauptung. Der Markenname einer Quelle ersetzt keinen passenden Beleg.",
        "c03 nennt drei unabhängige Empfehlungen aus ai-fanout.com, SEO Fanout und Crawl Foundry. Die sichtbare Eigentümeroffenlegung widerspricht dieser Einordnung: Die Angebote haben denselben Eigentümer. Das Urteil lautet contradicted; eine ehrliche Beschreibung nennt den verbundenen Workflow. Gemeinsames Eigentum macht einen technischen Beleg nicht unbrauchbar, aber nicht unabhängig.",
        "Alle drei Prüfungen nennen Datum und Belegstelle. Für deinen eigenen Fall musst du den tatsächlichen Claim und seine Quelle einsetzen. Kopiere das supported-Urteil nicht auf einen anderen Satz, nur weil dessen URL ähnlich aussieht."
      ]:[
        "c01 points to Google's section on the continuing relevance of SEO in generative search. This primary source supports the general statement. Its verdict is supported and its scope is general_guidance. It does not measure an individual outcome for your article.",
        "c02 uses the same source for the invented claim that our page therefore ranks first. The document contains no such site measurement. The verdict is unsupported and the next task is removing the ranking claim. A source's brand name is not a substitute for relevant evidence.",
        "c03 calls ai-fanout.com, SEO Fanout and Crawl Foundry three independent endorsements. The visible ownership disclosure contradicts that description: the services share an owner. The verdict is contradicted; an accurate description names the connected workflow. Common ownership does not make technical evidence unusable, but it does not make it independent.",
        "All three checks retain a date and evidence location. Substitute the actual claim and source for your work. Do not copy a supported verdict onto another sentence simply because its URL looks similar."
      ]},
      {id:"source-review-output",title:de?"Offene Belege werden zu einem konkreten Rechercheauftrag":"Turn evidence gaps into a concrete research assignment",paragraphs:de?[
        "Fasse die Ergebnisse nach Handlung zusammen: belastbare Aussagen verwenden, zu breite Formulierungen enger schreiben, widersprochene Behauptungen korrigieren und offene Quellen beschaffen. Ein einziges Qualitätslabel für die gesamte Domain verdeckt diese Unterschiede.",
        "Gib die Belegregister-Zeile an die Redaktion weiter. Ein Brief sollte Quelle, nötige Prüfung und Abnahme enthalten; ein Ergebnisbericht sollte Urteil und Grenze erhalten. Wenn du Provider-Material weitergeben willst, gelten dessen eigene Rechte und deine Freigabe weiterhin. Insbesondere entfernt der lokale Verlauf hier Gemini-Grounding- und Suchvorschlagsdaten; das Arbeitsblatt ist kein Umweg für deren Archivierung.",
        "Plane eine neue Prüfung, wenn eine zeitabhängige Aussage wieder veröffentlicht oder wesentlich geändert wird. Die Datei bleibt ein Review-Arbeitsprodukt. Sie misst weder, wie häufig ein Consumer-Produkt deine Seite zitiert, noch welchen Rank sie erreicht."
      ]:[
        "Group results by action: use supported statements, narrow overbroad wording, correct contradicted claims and obtain missing sources. One quality label for an entire domain hides these differences.",
        "Pass the relevant register row to the editor. A brief should retain the source, required check and acceptance evidence; a report should retain the verdict and limit. Provider material still has its own rights and sharing permissions. This site's local history removes Gemini grounding and search-suggestion data; the worksheet is not a route around that retention boundary.",
        "Plan another review when a time-sensitive statement is republished or substantially changed. The file remains a review artifact. It measures neither how often a consumer product cites your page nor the rank it reaches."
      ],references:[ref(1,"query-fanout-report-template","query-fanout-report-vorlage","report findings and limits","Befunde und Grenzen berichten"),ref(0,"fanout-content-brief","content-brief-aus-fanout","create an evidence-led content brief","einen belegten Content-Brief erstellen")]}
    ]};

  const experiment:LibraryArticle={...shared,number:"17",category:"Method",slug:de?"fanout-experiment-vorlage":"fanout-experiment-template",pairedSlug:de?"fanout-experiment-template":"fanout-experiment-vorlage",
    image:"/images/guides/fanout-variation.webp",imageAlt:de?"Drei mit Zeit, Sprache und Land beschriftete Reihen zeigen unterschiedliche verzweigte Suchpfade.":"Three rows labelled time, language and country show different branching search paths.",
    title:de?"Query-Fanout-Experiment: eine Vorlage für saubere Wiederholungen":"A query fanout experiment template for repeatable review",
    seoTitle:de?"Query Fanout Experiment Vorlage: Protokoll und Beispiel":"Query Fanout Experiment Template: Protocol and Example",
    shortTitle:de?"Wiederholungen planen":"Plan repeat runs",
    description:de?"Plane Wiederholungen mit festen Bedingungen, Kosten- und Rechtegrenzen. Die Vorlage trennt abgeschlossene Null-Query-Läufe von Fehlern und Timeouts.":"Plan repeat runs with fixed conditions, cost and rights limits. The template separates completed zero-query observations from failures and timeouts.",
    primaryIntent:de?"Wiederholte Beobachtungen mit vorher festgelegten Vergleichsregeln protokollieren.":"Record repeated observations using comparison rules defined beforehand.",
    answer:de?"Ein brauchbares Fanout-Experiment legt Frage, Bedingungen, Vergleich und Abbruchregel vor dem Lauf fest. Zähle abgeschlossene Null-Query-Beobachtungen und fehlgeschlagene Versuche getrennt. Die Vorlage organisiert den Versuch; sie ist kein veröffentlichter Benchmark.":"A useful fanout experiment defines the question, conditions, comparison and stop rule before running. Count completed zero-query observations separately from failed attempts. The template organises the experiment; it is not a published benchmark.",
    useWhen:de?"Wenn vorhandene erlaubte Daten eine eng formulierte Frage nicht beantworten. Das ausgefüllte Register enthält nur erfundene Zustände und verursacht keine API-Kosten.":"Use this when existing permitted data cannot answer a narrow question. The completed ledger contains only invented states and incurs no API cost.",
    relatedSlugs:de?["warum-fanout-ergebnisse-schwanken","ki-modelle-vergleichen","query-fanout-report-vorlage"]:["why-ai-fanout-results-change","compare-ai-model-searches","query-fanout-report-template"],
    sections:[
      {id:"pre-register",title:de?"Die Frage und den Vergleich vorab festlegen":"Define the question and comparison beforehand",paragraphs:de?[
        "Untersuche eine begrenzte Frage: etwa ob deine Auswertung einen abgeschlossenen Lauf ohne Query-Feld von einem Timeout unterscheiden kann. Dafür kann bereits eine synthetische Fixture genügen. Ein neuer bezahlter Provider-Lauf ist erst sinnvoll, wenn vorhandenes erlaubtes Material die tatsächliche Forschungsfrage nicht beantwortet.",
        "Halte Endpoint, exakte Modellkennung, Datum, Thema, Markt, Sprache und Tool-Konfiguration fest. Native API-Beobachtungen und modellierte Ideen bilden verschiedene Datenklassen. Du kannst sie beschreiben, aber nicht unbemerkt zu derselben beobachteten Suchmenge zusammenzählen.",
        "Lege auch die Umformungen vorab fest. Exakte Strings, normalisierte Strings und gemeinsame Domains beantworten unterschiedliche Fragen. Wenn du Großschreibung oder Leerraum vereinheitlichst, bewahre den Originaltext daneben. Eine Normalisierung erzeugt keine neue Query-/Quellenbeziehung.",
        "Die Markdown-Vorlage verbindet Bedingungen, Vergleichsregeln, Versuchsregister und Löschfrist. Im ausgefüllten Beispiel bleiben Provider- und Modellkennungen Platzhalter, weil gar kein tatsächlicher Response behauptet wird. Ersetze sie erst durch Angaben, die du wirklich geprüft hast."
      ]:[
        "Investigate a bounded question: for example, whether your review distinguishes a completed run without a query field from a timeout. A synthetic fixture may already answer that. A new paid provider run is useful only when existing permitted material cannot answer the actual research question.",
        "Record endpoint, exact model identifier, date, topic, market, language and tool configuration. Native API observations and modelled ideas are different evidence classes. You can describe both, but cannot silently count them as one observed search set.",
        "Define transformations beforehand too. Exact strings, normalised strings and shared domains answer different questions. If you standardise case or whitespace, retain the original text alongside it. Normalisation creates no new query-to-source relationship.",
        "The Markdown template connects conditions, comparison rules, an attempt ledger and a disposal deadline. In the example, provider and model identifiers remain placeholders because no actual response is claimed. Replace them only with information you have really checked."
      ],downloads:files("fanout-experiment","md",de?"Leeres Versuchsprotokoll (Markdown)":"Blank experiment protocol (Markdown)",de?"Synthetisches Versuchsregister (Markdown)":"Synthetic attempt ledger (Markdown)"),references:[ref(2,"compare-ai-model-searches","ki-modelle-vergleichen","compare API observations","API-Beobachtungen vergleichen")]},
      {id:"states-denominator",title:de?"Der Nenner enthält abgeschlossene Läufe, keine erfundenen Nullwerte":"Use completed runs as the denominator without inventing zeros",paragraphs:de?[
        "In unserer Lehrdatei ist Versuch A abgeschlossen und exponiert null Query-Strings. Versuch B läuft in einen Timeout und hat eine unbekannte Query-Zahl. Es gibt damit einen abgeschlossenen Lauf und einen separat berichteten Fehlversuch. Die Aussage zwei Läufe lieferten keine Queries wäre falsch.",
        "Notiere fehlende Modell-/Verbrauchsangaben als unbekannt. Ein Timeout verrät nicht, ob der Provider zuvor intern gesucht hat oder Kosten angefallen sind. Die synthetische Übung hat keine Kosten verursacht; bei einem echten Versuch brauchst du tatsächliche Verbrauchsangaben oder eine klar beschriftete Schätzung.",
        "Ein einzelner erfolgreicher Vergleich kann Unterschiede beschreiben, aber keine stabile Wahrscheinlichkeit ableiten. Wähle Wiederholungszahl und Auswertung anhand deiner konkreten Frage, Datenrechte und Kosten. Nenne Abweichungen statt nachträglich unpassende Läufe aus einer Ergebnisgeschichte zu entfernen.",
        "Bewahre Query-, Aktions- und Laufquellen in ihrem vorhandenen Umfang. Eine Quelle im Run darf nicht jeder Query zugeordnet werden, nur weil dein Vergleich dafür eine rechteckige Tabelle erwartet."
      ]:[
        "In the teaching file, attempt A completes and exposes zero query strings. Attempt B times out and has an unknown query count. That leaves one completed run and one separately reported failed attempt. Saying two runs returned no queries would be incorrect.",
        "Record missing model or usage information as unknown. A timeout does not establish whether the provider searched internally or incurred cost. The synthetic exercise incurred no costs; a real experiment needs actual usage information or a clearly labelled estimate.",
        "One successful comparison may describe differences but cannot establish a stable probability. Choose repetitions and analysis for the specific question, permissions and budget. Record deviations instead of silently removing inconvenient attempts from the outcome story.",
        "Preserve query, action and run sources at their existing scope. A run source cannot be assigned to every query simply because your comparison expects a rectangular table."
      ]},
      {id:"bounded-research",title:de?"Kosten, Aufbewahrung und Veröffentlichung getrennt regeln":"Set separate cost, retention and publication boundaries",paragraphs:de?[
        "Definiere ein hartes Budget und einen Abbruchpunkt, bevor du neue Anfragen startest. Das Protokoll ist keine Erlaubnis für bezahlte Forschung. Ebenso bedeutet eine private Prüfmöglichkeit nicht, dass rohe Provider-Ausgaben öffentlich archiviert oder als Benchmark veröffentlicht werden dürfen.",
        "Der freiwillige Browser-Verlauf dieses Tools speichert höchstens 20 Läufe für 30 Tage und entfernt Gemini-Grounding-/Suchvorschlagsdaten. Er ist kein unbegrenztes Forschungsarchiv. Plane Speicherort, erlaubte Felder und Löschdatum passend zu deinem tatsächlichen Vertrag.",
        "Der Abschlussbericht nennt Bedingungen, abgeschlossene Versuche, Fehlversuche und die Aussagegrenze. Er soll eine nachvollziehbare Beobachtung berichten, keine Consumer-Suchspur, Ranking-Chance oder Markt-Nachfrage erfinden. Für die Wirkung deiner Content-Änderung braucht es einen eigenen Website-Messplan."
      ]:[
        "Define a hard budget and stop point before making new requests. The protocol is not permission for paid research. A private review opportunity likewise does not authorise a public raw-output archive or benchmark.",
        "This tool's optional browser history retains at most 20 runs for 30 days and removes Gemini grounding and search-suggestion data. It is not an unrestricted research archive. Plan the storage location, permitted fields and disposal date for your actual agreement.",
        "The final report states conditions, completed attempts, failures and limits. It should report a reviewable observation without inventing consumer search traces, ranking chances or market demand. The effect of a content change needs a separate website measurement plan."
      ],references:[ref(2,"measure-fanout-content-changes","fanout-content-aenderungen-messen","measure website content changes","Website-Änderungen messen"),ref(0,"query-fanout-report-template","query-fanout-report-vorlage","report a bounded observation","eine begrenzte Beobachtung berichten")]}
    ]};

  const report:LibraryArticle={...shared,number:"18",category:"Data standard",slug:de?"query-fanout-report-vorlage":"query-fanout-report-template",pairedSlug:de?"query-fanout-report-template":"query-fanout-report-vorlage",
    title:de?"Query-Fanout-Bericht: Befunde, Grenzen und nächste Entscheidungen":"A query fanout report template for findings and next decisions",
    seoTitle:de?"Query Fanout Bericht Vorlage: editierbar mit Beispiel":"Query Fanout Report Template: Editable Worked Example",
    shortTitle:de?"Fanout-Bericht erstellen":"Create a fanout report",
    description:de?"Berichte Fanout-Ergebnisse mit einer editierbaren Vorlage und einem annotierten Beispiel. Trenne Befund, Hypothese, Empfehlung und noch fehlende Messung.":"Report fanout results with an editable template and annotated example separating findings, hypotheses, recommendations and missing measurements.",
    primaryIntent:de?"Einem Team nachvollziehbar sagen, was geprüft wurde und welche Entscheidung als Nächstes ansteht.":"Explain to a team what was reviewed and which decision comes next.",
    answer:de?"Ein Fanout-Bericht nennt zuerst die erbetene Entscheidung und den tatsächlich geprüften Datenumfang. Danach folgen Befunde mit Belegen, getrennte Hypothesen und konkrete Empfehlungen. Fehlende Nachfrage- oder Wirkungsmessung bleibt ausdrücklich fehlend.":"A fanout report starts with the requested decision and the data actually reviewed. It then gives evidenced findings, separate hypotheses and concrete recommendations. Missing demand or outcome measurements remain explicitly missing.",
    useWhen:de?"Für den Rückblick nach einer Prüfung. Die ausgefüllte Lehrdatei berichtet einen fiktiven Redaktionsauftrag, keine Kunden-Erfolge oder neuen Provider-Läufe.":"Use this after a review. The completed teaching file reports a fictional editorial assignment, not client successes or new provider runs.",
    relatedSlugs:de?["fanout-quellen-pruefen","fanout-content-aenderungen-messen","content-brief-aus-fanout"]:["fanout-source-audit","measure-fanout-content-changes","fanout-content-brief"],
    sections:[
      {id:"report-scope",title:de?"Mit der Entscheidung beginnen, die der Bericht ermöglichen soll":"Start with the decision the report should support",paragraphs:de?[
        "Ein Team braucht selten nur eine lange Query-Liste. Es muss etwa entscheiden, ob es einen Kostenabschnitt recherchiert, eine vorhandene Seite erweitert oder eine Frage ausschließt. Benenne diesen Auftrag und den Empfänger zuerst. Ein Bericht für die Redaktion braucht andere Details als eine private Parser-Diagnose.",
        "Schreibe Dateien, Versionen und Zeitpunkte auf. Erhalte die Datenklassen: native API-Beobachtung, modellierte Idee, redaktionelle Frage und menschliche Suchdaten. Eine Auswahl ist kein vollständiger Run. Nenne deshalb eingeschlossene und ausgeschlossene Fragen sowie Quellen, die nur auf Laufebene vorhanden sind.",
        "Die Markdown-Vorlage hält Finding, evidence class, Belegstelle, zulässige Aussage und Grenze nebeneinander. Für jede Empfehlung folgen Verantwortlicher, Zielseite und Abnahme. Das macht den Bericht auch dann nutzbar, wenn die nächste Person den ursprünglichen Dialog nicht mehr öffnen kann.",
        "Lade zusätzlich den annotierten Lehrbericht herunter. Er überprüft sieben eigene Fragen und nennt ungeprüfte Nachfrage. Die Datei ist rückblickend über die Übung; der Content-Brief ist dagegen der prospektive Schreibauftrag. Beide Dokumente haben unterschiedliche Aufgaben."
      ]:[
        "A team rarely needs only a long query list. It needs to decide whether to research a cost section, improve an existing page or exclude a question. State that assignment and recipient first. An editorial report needs different details from a private parser diagnosis.",
        "Record files, versions and timestamps. Preserve the evidence classes: native API observation, modelled idea, editorial question and human search data. A selection is not a complete run. State included and excluded questions, along with sources available only at run scope.",
        "The Markdown template places the finding, evidence class, location, supported claim and limit side by side. Each recommendation then has an owner, target and acceptance evidence. The report remains useful even when the next person cannot open the original dialog.",
        "Download the annotated teaching report too. It reviews seven original questions and records unchecked demand. The file reports retrospectively on the exercise; a content brief is the prospective writing assignment. The documents serve different tasks."
      ],downloads:files("fanout-report","md",de?"Editierbare Berichtsvorlage (Markdown)":"Editable report template (Markdown)",de?"Annotierter Musterbericht (Markdown)":"Annotated example report (Markdown)"),references:[ref(3,"fanout-content-brief","content-brief-aus-fanout","create the writing brief","den Schreib-Brief erstellen")]},
      {id:"report-example",title:de?"Befund, Hypothese und Empfehlung an einem Beispiel trennen":"Separate findings, hypotheses and recommendations in one example",paragraphs:de?[
        "F01 beschreibt die Zuordnung der sieben redaktionellen Fragen. Auswahl und Kosten bleiben beim selben fiktiven Kaufberater, Import bildet eine eigene Bedienaufgabe, SQL wird ausgeschlossen. Die Aussage betrifft die Gruppierung im Arbeitsblatt. Sie belegt weder eine Provider-Suche noch Suchnachfrage.",
        "F03 hält fest, dass das GSC-Beispiel keine Messwerte enthält. Diese fehlende Prüfung wird nicht zur Behauptung Nachfrage null. F04 nennt die zulässige allgemeine Aussage aus der Quellenprüfung und grenzt sie von einem individuellen Ranking-Ergebnis ab.",
        "H01 vermutet, ein geprüfter Kostenabschnitt könnte einem fünfköpfigen Team bei der Auswahl helfen. R01 empfiehlt deshalb einen begrenzten Rechercheauftrag mit aktuellen Nutzerbedingungen und nachvollziehbarer Rechnung. Der Brief soll noch keine ungeprüfte Siegerempfehlung produzieren.",
        "Übernimm aus dem Messbeispiel keine synthetischen Zahlen als angebliche Ergebnisse dieses Berichts. Der Musterbericht weist ausdrücklich darauf hin, dass die fiktive Website-Änderung noch nicht veröffentlicht wurde und Klicks, Rankings sowie Conversions nicht gemessen sind."
      ]:[
        "F01 describes the grouping of seven editorial questions. Selection and cost stay with the same fictional buying guide, import is a separate operation and SQL is excluded. The claim concerns the worksheet's grouping. It establishes neither a provider search nor human demand.",
        "F03 records that the GSC example contains no measurements. That missing check is not converted into a zero-demand claim. F04 names the supported general statement from the source audit and distinguishes it from an individual ranking outcome.",
        "H01 suggests that a verified cost section could help a five-person team choose a plan. R01 therefore recommends a bounded research assignment with current seat conditions and a reproducible calculation. The brief should not produce an unchecked winner recommendation.",
        "Do not transfer synthetic arithmetic from the measurement exercise into this report as observed results. The example explicitly states that the fictional website change has not been released and clicks, rankings and conversions have not been measured."
      ],references:[ref(1,"fanout-source-audit","fanout-quellen-pruefen","audit the supporting sources","die tragenden Quellen prüfen")]},
      {id:"report-handoff",title:de?"Ein Bericht endet mit einer überprüfbaren Folgeaufgabe":"End the report with a checkable follow-up",paragraphs:de?[
        "Benutze konkrete nächste Schritte: aktuelle Bedingungen beschaffen, einen Importweg testen, eine Seitenänderung freigeben oder eine vergleichbare Nachmessung durchführen. Nenne Verantwortlichen und Abnahmebeleg. Eine unspezifische Empfehlung mehr Content zu veröffentlichen lässt den Empfänger mit derselben Frage zurück.",
        "Prüfe vor Weitergabe den Empfängerkreis und erlaubte Datenfelder. Entferne private Eingaben und Account-Kennungen; kläre die Weitergabe von Provider-Material gesondert. Rohe Queries und Fragmentdaten gehören nicht in Nutzungsanalyse-Events. Die Vorlagen benötigen keine neue Tracking-Integration.",
        "Nenne gemeinsame Eigentümer bei verbundenen Angeboten. ai-fanout.com, SEO Fanout und Crawl Foundry bilden einen verbundenen Workflow, keine unabhängige Bestätigung der Befunde. Füge zum Schluss Baseline, nächste Prüffrist und offene Grenzen hinzu, damit aus dem Bericht ein tatsächlich nachverfolgbarer Auftrag wird."
      ]:[
        "Use concrete next steps: obtain current conditions, test an import route, approve a page change or conduct a comparable follow-up. Name an owner and acceptance evidence. An unspecified recommendation to publish more content leaves the recipient with the same unanswered question.",
        "Before sharing, review the audience and permitted fields. Remove private input and account identifiers; check provider-material sharing rights separately. Raw queries and fragment payloads do not belong in usage analytics events. These templates require no new tracking integration.",
        "Disclose shared ownership for connected services. ai-fanout.com, SEO Fanout and Crawl Foundry form a connected workflow, not independent confirmation of the findings. End with the baseline, next review date and open limits so the report creates a task that can actually be followed up."
      ],references:[ref(2,"measure-fanout-content-changes","fanout-content-aenderungen-messen","plan the follow-up measurement","die Nachmessung planen")]}
    ]};
  return [priorities,measurement,sources,experiment,report];
}

export function seoWorkflowSections(de:boolean):LibrarySection[]{
  const link=(afterParagraph:number,en:string,german:string,enLabel:string,deLabel:string):LibraryReference=>({afterParagraph,before:de?"Für diesen Schritt kannst du":"For this step, you can",label:de?deLabel:enLabel,href:de?`/de/lernen/${german}`:`/library/${en}`});
  return [
    {id:"workflow-evidence",title:de?"Von der Query zur Frage, die deine Seite wirklich beantworten soll":"Move from a query to the question your page needs to answer",paragraphs:de?[
      "Query Fanout liefert Recherchematerial. Eine native Query ist eine in einem API-Lauf offengelegte Formulierung; eine modellierte Idee ist ein Vorschlag. Keine der beiden enthält automatisch Nachfrage, Wettbewerb oder den Beweis, dass deiner Website ein Artikel fehlt. Beginne deshalb mit einer Leserentscheidung und erhalte die Herkunft jeder Frage.",
      "Der durchgehende eigene Lehrfall betrifft einen fiktiven Kaufberater für SEO-Software: sieben redaktionelle Fragen, keine neue Provider-Ausgabe. q01–q02 betreffen die Auswahl, q03–q04 Nutzerkosten, q05–q06 CSV-Import und UTF-8, q07 SQL. Der Zweck ist eine nachvollziehbare Seitenentscheidung, kein erfundener Kundenerfolg.",
      "Bewahre exakte Fragen und stabile IDs im Cluster-Arbeitsblatt. Der Kaufberater erhält Auswahl und Kosten als Abschnitte. Import wird zu einem eigenen getesteten Bedienauftrag; SQL fällt aus diesem Auftrag heraus. Unterschiedliche Wörter können damit denselben Job bedienen, während ähnliche Wörter verschiedene Aufgaben bezeichnen."
    ]:[
      "Query fanout supplies research material. A native query is a phrase exposed within one API run; a modelled idea is a suggestion. Neither automatically supplies demand, competition or proof that your site lacks an article. Start with a reader decision and preserve each question's origin.",
      "The original end-to-end exercise concerns a fictional SEO-software buying guide: seven editorial questions and no new provider output. q01–q02 cover selection, q03–q04 seat costs, q05–q06 CSV import and UTF-8, and q07 SQL. The purpose is a reviewable page decision, not an invented customer success.",
      "Retain exact questions and stable IDs in the clustering worksheet. The buying guide receives selection and cost sections. Import becomes a separate tested operational assignment; SQL falls outside this task. Different wording may serve the same job, while similar wording may describe different tasks."
    ],references:[link(0,"export-fanout-queries","fanout-queries-exportieren","preserve export evidence","Export-Belege erhalten"),link(2,"cluster-fanout-queries","fanout-queries-clustern","cluster by reader task","nach Leseraufgabe clustern")]},
    {id:"workflow-demand",title:de?"Nachfrage und Priorität prüfen, bevor du einen Schreibauftrag vergibst":"Check demand and priority before assigning the article",paragraphs:de?[
      "Ordne den Cluster tatsächlich sichtbaren menschlichen Suchfragen und passenden Zielseiten zu. Im GSC-Arbeitsblatt stehen Property, Datum und Filter neben der Zuordnung. Fehlende Query-Zeilen bleiben eine Datenbegrenzung. Das Lehrbeispiel besitzt keine GSC-Messwerte und behauptet deshalb keine bestätigte Nachfrage.",
      "Priorisiere nun den nächsten prüfbaren Schritt. Softwareauswahl braucht echte Funktions- und Preisbelege. Der Kostenabschnitt benötigt aktuelle Nutzerbedingungen. Import braucht einen erfolgreichen Dateitest. Diese Aufgaben unterscheiden sich in Belegbedarf und Aufwand, ohne dass daraus ein universeller Ranking-Score entsteht.",
      "Prüfe die bestehende Seite, bevor du eine neue URL beschließt. Die Fragen nach Kosten für fünf Nutzer und enthaltenen Plätzen gehören im Beispiel zum gleichen Kaufberater. Für diese Kombination reicht ein neuer Abschnitt, wenn er die Entscheidung vollständig unterstützt. Das konkrete Import-Ergebnis rechtfertigt dagegen eine separate Anleitung mit eigenem Test."
    ]:[
      "Map the cluster to visible human search questions and relevant pages. The GSC worksheet keeps property, date and filters beside the mapping. Missing query rows remain a coverage limitation. The exercise has no GSC measurements and therefore claims no established demand.",
      "Now prioritize the next checkable task. Software selection needs real feature and price evidence. The cost section needs current seat conditions. Import needs a successful file test. The tasks differ in evidence and effort without producing a universal ranking score.",
      "Review the existing page before deciding on a new URL. Questions about five-user cost and included seats belong to the same buying guide in the exercise. One new section is sufficient if it fully supports that decision. The concrete import outcome instead supports a separate tutorial with its own test."
    ],references:[link(0,"fanout-queries-search-console","fanout-queries-search-console","validate with Search Console","mit Search Console prüfen"),link(1,"prioritize-fanout-queries","fanout-queries-priorisieren","prioritize the next action","die nächste Aktion priorisieren")]},
    {id:"workflow-brief",title:de?"Einen konkreten Brief mit Belegregister und Abnahme schreiben":"Write a concrete brief with evidence and acceptance criteria",paragraphs:de?[
      "Der Brief beschreibt das Ergebnis für den Leser: Ein fünfköpfiges Team soll Funktionen, Rechte und vollständige Nutzerkosten eines passenden Plans nachvollziehen können. Die ausgefüllte Vorlage enthält Fragen, nötige Quellen, Aufbau und Ausschlüsse. Ein ungeprüfter Preis wird zum Rechercheauftrag, nicht zur fertigen Empfehlung.",
      "Prüfe jede geplante Aussage gegen ihre Belegstelle. Allgemeine Google-Dokumentation kann die Relevanz von SEO erklären, aber keinen ersten Platz deiner Seite beweisen. Eine Quellenliste ohne passende Claim-Zuordnung genügt nicht. Im Audit bleiben gestützte, offene und widersprochene Aussagen getrennt.",
      "Die Abnahme prüft die tatsächliche Leseraufgabe. Für einen Kostenabschnitt gehören datierte Bedingungen und eine nachvollziehbare Rechnung dazu; für eine Importanleitung eine korrekt importierte eigene Datei. Übernimm nicht jede Fanout-Formulierung als Zwischenüberschrift. Ein Abschnitt soll eine Aufgabe beantworten, statt nur Begriffe zu wiederholen."
    ]:[
      "The brief defines the reader's outcome: a five-person team should understand features, permissions and full seat costs of an appropriate plan. The completed template contains questions, required sources, structure and exclusions. An unchecked price becomes a research task rather than a finished recommendation.",
      "Check every planned claim against its evidence location. General Google documentation may explain SEO's relevance but cannot prove your page ranks first. A source list without claim attribution is insufficient. The audit retains supported, open and contradicted statements separately.",
      "Acceptance checks the actual reader task. A cost section needs dated conditions and a reproducible calculation; an import tutorial needs a correctly imported original file. Do not promote every fanout phrase into a heading. A section should answer a task rather than repeat terms."
    ],references:[link(0,"fanout-content-brief","content-brief-aus-fanout","use the completed content brief","den ausgefüllten Content-Brief nutzen"),link(1,"fanout-source-audit","fanout-quellen-pruefen","audit the sources","die Quellen prüfen")]},
    {id:"workflow-review",title:de?"Veröffentlichen, messen und eine nächste Entscheidung treffen":"Publish, measure and make the next decision",paragraphs:de?[
      "Lege die Messdefinition vor Veröffentlichung fest. Dokumentiere Release und bestätigten Recrawl getrennt. Vergleiche eine feste URL-/Query-Auswahl mit denselben Filtern und passenden vollständigen Zeitfenstern. Ein korrektes Deployment belegt die Veröffentlichung, aber noch keine Suchentwicklung.",
      "In der synthetischen Messübung steigen Klicks von 10 auf 20 und Impressionen von 1000 auf 2000; die CTR bleibt ein Prozent. Das Rechenbeispiel zeigt, weshalb eine höhere Klickzahl nicht automatisch eine bessere Klickrate oder isolierte Fanout-Wirkung belegt. Es enthält keine Daten dieser Website.",
      "Berichte Beobachtung, Hypothese und Empfehlung getrennt. Der nächste Auftrag kann eine fehlende Quelle, eine neue Prüfung oder eine kleine Überarbeitung sein. Ein kontrollierbarer Zyklus mit echten Arbeitsprodukten ist das Ziel: Auswahl, Cluster, GSC-Zuordnung, Priorität, Brief, Quellencheck, Release und Nachmessung."
    ]:[
      "Define measurement before publishing. Record release and confirmed recrawl separately. Compare a fixed URL/query set using the same filters and suitable complete reporting windows. A correct deployment proves publication but not yet search development.",
      "In the synthetic measurement exercise, clicks rise from 10 to 20 and impressions from 1000 to 2000 while CTR stays at one percent. The arithmetic explains why a higher click count does not automatically establish better CTR or isolated fanout impact. It contains none of this website's data.",
      "Report observations, hypotheses and recommendations separately. The next assignment may be a missing source, another check or a small revision. Aim for a reviewable cycle with real work products: selection, clusters, GSC mapping, priority, brief, source check, release and follow-up."
    ],references:[link(0,"measure-fanout-content-changes","fanout-content-aenderungen-messen","measure content changes","Content-Änderungen messen"),link(2,"query-fanout-report-template","query-fanout-report-vorlage","use the annotated report","den annotierten Bericht nutzen")]}
  ];
}
